// 0) openingHours'ı her formattan tek satır string'e çevir
function formatOpeningHours(oh) {
  if (!oh) return "N/A";

  if (typeof oh === "string") return oh.trim() || "N/A";

  if (Array.isArray(oh)) {
    const s = oh.filter(Boolean).map(String).map(x => x.trim()).filter(Boolean).join(" | ");
    return s || "N/A";
  }

  if (typeof oh === "object") {
    // Google tarzı
    if (Array.isArray(oh.weekday_text)) {
      const s = oh.weekday_text.map(String).map(x => x.trim()).filter(Boolean).join(" | ");
      return s || "N/A";
    }

    // Senin SS'deki gibi: { Thursday: "8 AM-2 AM", Friday: "..."}
    const entries = Object.entries(oh)
      .filter(([k, v]) => typeof v === "string" && v.trim() !== "")
      .map(([k, v]) => `${k}: ${v.trim()}`);

    if (entries.length) return entries.join(" | ");
  }

  return "N/A";
}

// 1) HTTP Request çıktısından content'i çek
const first = $input.first().json;

const content =
  first?.choices?.[0]?.message?.content ??
  first?.choices?.[0]?.text ??
  first?.message?.content ??
  first?.content ??
  "";

// 2) ```json ... ``` temizle
const cleaned = String(content)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// 3) JSON parse (güvenli)
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [
    {
      json: {
        _error: "Model JSON döndürmedi / parse edilemedi",
        _raw: cleaned,
      },
    },
  ];
}

// 4) Array'e çevir
let arr;
if (Array.isArray(parsed)) arr = parsed;
else if (parsed && Array.isArray(parsed.data)) arr = parsed.data;
else if (parsed && typeof parsed === "object") arr = [parsed];
else arr = [];

// 5) Normalize + UUID key bozulmalarını düzelt
const normalizeOne = (item) => {
  const uuid =
    item.UUID ??
    item["UUID\n"] ??
    item["UUID\r\n"] ??
    item["UUID "] ??
    item.uuid ??
    item.id ??
    item.place_id ??
    item.placeId ??
    "";

  const rawNumber = item.Number ?? item.number ?? item.phoneNumber ?? item.phone ?? "";
  const number = String(rawNumber).replace(/^\+/, "").trim() || "N/A";

  // opening hours: hem "Opening Hours" hem openingHours hem opening_hours + object support
  const ohRaw =
    item["Opening Hours"] ??
    item.OpeningHours ??
    item.OpeningHoursText ??
    item.openingHours ??
    item.opening_hours ??
    item.hours ??
    null;

  return {
    UUID: String(uuid).trim(),
    Name: item.Name ?? item.name ?? item.title ?? "N/A",
    Background: item.Background ?? item.background ?? item.type ?? "N/A",
    Address: item.Address ?? item.address ?? "N/A",
    Number: number,
    Website: item.Website ?? item.website ?? "N/A",
    Rating: item.Rating ?? item.rating ?? "N/A",

    // 🔥 Sheet kolon adıyla birebir: "Opening Hours"
    "Opening Hours": formatOpeningHours(ohRaw),

    Email: item.Email ?? item.email ?? "N/A",
  };
};

// 6) n8n'in beklediği şekilde item item döndür
return arr.map((x) => ({ json: normalizeOne(x) }));
